const f = $json;
const referenceId = String(f['Inspection Reference ID'] || '').trim();
const lineItems = String(f['Line Items / Scope'] || '').trim();
const amount = parseInt(String(f['Quote Amount (INR)'] || '0').replace(/[^0-9]/g, ''), 10) || 0;
let advancePercent = parseInt(String(f['Advance %'] || '').replace(/[^0-9]/g, ''), 10);
if (isNaN(advancePercent)) advancePercent = 50;
let validityDays = parseInt(String(f['Validity (days)'] || '').replace(/[^0-9]/g, ''), 10);
if (isNaN(validityDays)) validityDays = 15;
const terms = String(f['Terms / Notes'] || '').trim();
const quoteNo = 'QT-' + referenceId + '-' + String(Date.now()).slice(-6);
return { json: { referenceId, lineItems, amount, advancePercent, validityDays, terms, quoteNo } };

const f = $json;
const referenceId = String(f['Inspection Reference ID'] || '').trim();
const decision = String(f['Decision'] || '').trim().toLowerCase() === 'won' ? 'won' : 'lost';
const finalAmount = parseInt(String(f['Final Amount (INR)'] || '0').replace(/[^0-9]/g, ''), 10) || 0;
const upiId = String(f['UPI ID or Payment Link'] || f['UPI ID for advance'] || '').trim() || 'upi://pay?pa=osmida@upi';
return { json: { referenceId, decision, finalAmount, upiId, isWon: decision === 'won' } };
